CREATE TABLE `member` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(20) COLLATE utf8mb4_bin NOT NULL COMMENT '로그인 아이디',
  `password` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT 'bcrypt 해시, 임시 비밀번호 가능',
