--
-- Table structure for table `member_stat`
--

DROP TABLE IF EXISTS `member_stat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member_stat` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `member_id` bigint NOT NULL,
  `season_id` varchar(10) COLLATE utf8mb4_bin NOT NULL COMMENT '시즌 ID (예: 1401, 1602)',
  `tier` varchar(15) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'MongoDB에서 복제된 티어 정보 (IRON, BRONZE, SILVER, GOLD, PLATINUM, EMERALD, DIAMOND, MASTER, GRANDMASTER, CHALLENGER)',
  `division` varchar(5) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'MongoDB에서 복제된 디비전 정보 (I, II, III, IV)',
  `league_point` int DEFAULT NULL COMMENT 'MongoDB에서 복제된 리그 포인트',
  `rank_win_rate` decimal(5,2) DEFAULT NULL COMMENT 'MongoDB에서 복제된 랭크 승률',
  `rank_wins` int DEFAULT NULL COMMENT 'MongoDB에서 복제된 랭크 승수',
  `rank_lose_rate` int DEFAULT NULL COMMENT 'MongoDB에서 복제된 랭크 패배율',
  `lasted_win_rate` decimal(5,2) DEFAULT NULL COMMENT 'MongoDB에서 복제된 최근 승률',
  `lasted_wins` int DEFAULT NULL COMMENT 'MongoDB에서 복제된 최근 승수',
  `lasted_losses` int DEFAULT NULL COMMENT 'MongoDB에서 복제된 최근 패배수',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_member_season` (`member_id`,`season_id`),
  CONSTRAINT `fk_ms_member` FOREIGN KEY (`member_id`) REFERENCES `member` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `member_stat`
--

LOCK TABLES `member_stat` WRITE;
/*!40000 ALTER TABLE `member_stat` DISABLE KEYS */;
